import{_ as i,a8 as t,o as n,c as d,ah as l,K as a}from"./chunks/framework.CgKDWdj8.js";import"./chunks/theme.CCmhGRzB.js";const k=JSON.parse('{"title":"观察者模式与发布-订阅模式","description":"","frontmatter":{"title":"观察者模式与发布-订阅模式","abstract":"观察者模式与发布-订阅模式的对比，涵盖两者处理一对多通知的结构差异、耦合程度及事件通道的解耦作用。","created":"2026-07-10T00:00:00.000Z","tags":["设计模式"],"type":"概念解释","category":["🛠️ 工程工具"]},"headers":[],"relativePath":"vault/Knowledge/Engineering/观察者模式与发布-订阅模式.md","filePath":"vault/Knowledge/Engineering/观察者模式与发布-订阅模式.md","lastUpdated":1790655645000}'),o={name:"vault/Knowledge/Engineering/观察者模式与发布-订阅模式.md"};function b(c,e,h,p,u,g){const r=t("NolebaseGitContributors"),s=t("NolebaseGitChangelog");return n(),d("div",null,[e[0]||(e[0]=l('<h1 id="观察者模式与发布-订阅模式" tabindex="-1">观察者模式与发布-订阅模式 <a class="header-anchor" href="#观察者模式与发布-订阅模式" aria-label="Permalink to “观察者模式与发布-订阅模式”">​</a></h1><p>两种处理一对多通知关系的模式，常被混淆但有关键区别。</p><h2 id="观察者模式-observer" tabindex="-1">观察者模式（Observer） <a class="header-anchor" href="#观察者模式-observer" aria-label="Permalink to “观察者模式（Observer）”">​</a></h2><p><strong>主题直接通知观察者</strong>，两者间存在直接依赖。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>Subject ──直接调用──▶ Observer[]</span></span></code></pre></div><ul><li>Subject 维护观察者列表 <code>addObserver / removeObserver / notify</code></li><li>状态变化时调用每个 Observer 的 <code>update()</code></li><li><strong>耦合</strong>：Subject 知道 Observer 接口</li></ul><h2 id="发布-订阅模式-pub-sub" tabindex="-1">发布-订阅模式（Pub-Sub） <a class="header-anchor" href="#发布-订阅模式-pub-sub" aria-label="Permalink to “发布-订阅模式（Pub-Sub）”">​</a></h2><p><strong>中间引入事件通道</strong>（Event Bus），发布者和订阅者完全解耦。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>Publisher ──emit──▶ Event Channel ──dispatch──▶ Subscriber[]</span></span></code></pre></div><ul><li>Publisher 不知道谁接收</li><li>Subscriber 不知道谁发出</li><li>支持多对多、消息过滤、异步投递</li></ul><h2 id="关键区别" tabindex="-1">关键区别 <a class="header-anchor" href="#关键区别" aria-label="Permalink to “关键区别”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>观察者</th><th>Pub-Sub</th></tr></thead><tbody><tr><td>耦合</td><td>Subject 依赖 Observer</td><td>完全解耦</td></tr><tr><td>通信</td><td>直接同步调用</td><td>通过事件通道</td></tr><tr><td>中介</td><td>无</td><td>Event Bus / Broker</td></tr><tr><td>典型例子</td><td>DOM EventListener</td><td>Vue EventBus、Redis Pub/Sub、MQTT</td></tr></tbody></table><h2 id="前端实践" tabindex="-1">前端实践 <a class="header-anchor" href="#前端实践" aria-label="Permalink to “前端实践”">​</a></h2><p>Vue 的响应式系统本质上是观察者（Dep → Watcher），Vue 3 的 <code>emitter</code> 和 React 的 <code>EventEmitter</code> 更接近 Pub-Sub。</p>',14)),a(r),a(s)])}const m=i(o,[["render",b]]);export{k as __pageData,m as default};
